class VADProcessor extends AudioWorkletProcessor{constructor(t){super();const e=t.processorOptions||{};this.targetSampleRate=e.targetSampleRate||16e3,this.targetFrameSize=e.targetFrameSize||512,this.nativeSampleRate=sampleRate,this.inputBuffer=[],this.outputBuffer=[]}resample(t){if(this.nativeSampleRate===this.targetSampleRate)return t;const e=this.nativeSampleRate/this.targetSampleRate,r=Math.floor(t.length/e),s=new Float32Array(r);for(let a=0;a<r;a++){const r=a*e,i=Math.floor(r),o=r-i,h=t[i]||0,n=t[Math.min(i+1,t.length-1)]||h;s[a]=h+(n-h)*o}return s}process(t,e,r){const s=t[0];if(s&&s.length>0){const t=s[0];for(let e=0;e<t.length;e++)this.inputBuffer.push(t[e]);const e=Math.ceil(this.targetFrameSize*this.nativeSampleRate/this.targetSampleRate);for(;this.inputBuffer.length>=e;){const t=this.inputBuffer.splice(0,e),r=this.resample(t);for(let t=0;t<r.length;t++)this.outputBuffer.push(r[t]);for(;this.outputBuffer.length>=this.targetFrameSize;){const t=this.outputBuffer.splice(0,this.targetFrameSize),e=new Float32Array(t);this.port.postMessage({type:"audioFrame",frame:e},[e.buffer])}}}return!0}}registerProcessor("vad-processor",VADProcessor);